import hmac
import hashlib
import os
import time
import sqlite3
from flask import Flask, request, jsonify, g
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))

DB_PATH = '/tmp/auth_service.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        api_key_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        rate_limit INTEGER NOT NULL DEFAULT 100
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        expires_at REAL NOT NULL,
        permissions TEXT NOT NULL DEFAULT 'read'
    )''')
    db.commit()
    db.close()

def constant_time_compare(a, b):
    """Compare two strings in constant time to prevent timing attacks."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

def hash_api_key(provided_key):
    """Derive a keyed (HMAC-SHA256) hash of the API key.

    Using an HMAC keyed with the server SECRET_KEY prevents offline
    precomputation / rainbow-table attacks against stored hashes.
    """
    return hmac.new(
        app.config['SECRET_KEY'].encode(),
        provided_key.encode(),
        hashlib.sha256
    ).hexdigest()

def generate_session_token(user_id, permissions, duration=3600):
    """Generate a signed session token."""
    expires_at = time.time() + duration
    random_part = secrets.token_hex(16)
    payload = f"{user_id}:{permissions}:{expires_at}:{random_part}"
    signature = hmac.new(
        app.config['SECRET_KEY'].encode(),
        payload.encode(),
        hashlib.sha256
    ).hexdigest()
    return f"{payload}:{signature}"

def validate_session_token(token):
    """Validate a session token and return its components."""
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, provided_sig = parts
    expected_sig = hmac.new(
        app.config['SECRET_KEY'].encode(),
        payload.encode(),
        hashlib.sha256
    ).hexdigest()
    # Use constant-time comparison for signature validation
    sig_valid = hmac.compare_digest(provided_sig, expected_sig)
    if not sig_valid:
        return None
    payload_parts = payload.rsplit(':', 3)
    if len(payload_parts) != 4:
        return None
    user_id, permissions, expires_at, _ = payload_parts
    if float(expires_at) < time.time():
        return None
    return {
        'user_id': int(user_id),
        'permissions': permissions,
        'expires_at': float(expires_at)
    }

def verify_api_key(username, provided_key):
    """Verify an API key against stored hash."""
    db = get_db()
    row = db.execute(
        'SELECT api_key_hash, role FROM users WHERE username = ?',
        (username,)
    ).fetchone()
    if row is None:
        # Perform dummy hash to prevent timing oracle on user existence
        hash_api_key('dummy')
        return None
    stored_hash = row['api_key_hash']
    computed_hash = hash_api_key(provided_key)
    if constant_time_compare(computed_hash, stored_hash):
        return {'username': username, 'role': row['role']}
    return None

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'api_key' not in data:
        return jsonify({'error': 'Missing credentials'}), 400
    user = verify_api_key(data['username'], data['api_key'])
    if user is None:
        return jsonify({'error': 'Invalid credentials'}), 401
    db = get_db()
    row = db.execute(
        'SELECT id FROM users WHERE username = ?',
        (user['username'],)
    ).fetchone()
    permissions = 'read,write,admin' if user['role'] == 'admin' else 'read'
    token = generate_session_token(row['id'], permissions)
    db.execute(
        'INSERT INTO sessions (token, user_id, expires_at, permissions) VALUES (?, ?, ?, ?)',
        (token, row['id'], time.time() + 3600, permissions)
    )
    db.commit()
    return jsonify({'token': token, 'permissions': permissions})

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    if not token:
        return jsonify({'error': 'No token provided'}), 401
    session = validate_session_token(token)
    if session is None:
        return jsonify({'error': 'Invalid token'}), 401
    if 'admin' not in session['permissions']:
        return jsonify({'error': 'Insufficient permissions'}), 403
    db = get_db()
    users = db.execute('SELECT id, username, role FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/api/data', methods=['GET'])
def get_data():
    token = request.headers.get('Authorization', '').replace('Bearer ', '')
    if not token:
        return jsonify({'error': 'No token provided'}), 401
    session = validate_session_token(token)
    if session is None:
        return jsonify({'error': 'Invalid token'}), 401
    return jsonify({'data': 'sensitive information', 'user_id': session['user_id']})

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000)
